//! `defines` — per-method record of the backing-reconcile module.

use super::exported_symbols;

pub(crate) fn defines(src: &str, sym: &str) -> bool {
    regex::Regex::new(&format!(r"\b(?:function|const|class)\s+{}\b", regex::escape(sym)))
        .map(|re| re.is_match(src))
        .unwrap_or(false)
        || exported_symbols(src).iter().any(|s| s == sym)
}
